/* Local prototype only. Production identity, referral verification and awards must be server-authoritative. */
window.Referral=(()=>{
 const KEY='flow-members-demo-v1';let state={active:null,members:[]},memoryOnly=false;
 try{const stored=JSON.parse(localStorage.getItem(KEY));if(stored&&Array.isArray(stored.members)){state.members=stored.members.filter(m=>m&&typeof m.id==='string'&&typeof m.name==='string'&&/^[A-Z0-9]{8}$/.test(m.code)&&typeof m.verified==='boolean').map(m=>({id:m.id,name:m.name.slice(0,24),code:m.code,verified:m.verified,ref:typeof m.ref==='string'?m.ref:'',created:typeof m.created==='string'?m.created:new Date().toISOString()}));state.active=state.members.some(m=>m.id===stored.active)?stored.active:null;}}catch{}
 const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
 function active(){return state.members.find(m=>m.id===state.active)}
 function displayName(){return escape(active()?.name||'테리')}
 function decorate(){const m=active();const name=m?.name||'테리';document.querySelectorAll('.profile b').forEach(n=>n.textContent=name);document.querySelectorAll('.profile .avatar,.header-right .avatar').forEach(n=>n.textContent=name.slice(0,1));}
 function write(){try{localStorage.setItem(KEY,JSON.stringify(state));memoryOnly=false;return true}catch{memoryOnly=true;return false}}
 function incoming(){const value=new URLSearchParams(location.search).get('ref')||'';return /^[A-Z0-9]{8}$/.test(value)?value:''}
 function link(m=active()){const url=new URL(location.href);url.search='';url.searchParams.set('ref',m.code);url.hash='join';return url.href}
 function code(){let value;do{value=Array.from(crypto.getRandomValues(new Uint8Array(8)),n=>'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[n%31]).join('')}while(state.members.some(m=>m.code===value));return value}
 const badge=m=>m.verified?'<span class="status-badge verified">데모 인증 완료</span>':'<span class="status-badge pending">인증 대기</span>';
 function invited(m){return state.members.filter(u=>u.ref===m.code)}
 function memberShell(title,subtitle,content){$('#breadcrumb').textContent='내 계정 / '+title;$('#desktop-nav').innerHTML=paths.map((p,i)=>`<a href="#${p}">${icon(i)}<span>${c().menus[i]}</span></a>`).join('');$('#mobile-nav').innerHTML=paths.map((p,i)=>`<a href="#${p}">${icon(i)}<span>${c().menus[i]}</span></a>`).join('');$('#main').innerHTML=`<div class="heading"><div><span class="eyebrow">MEMBERS & INVITATIONS</span><h1>${title}</h1><p>${subtitle}</p></div></div>${content}`;document.title=title+' | FLOW';Design.apply();decorate()}
 function render(page){if(page==='join'){const ref=incoming(),referrer=state.members.find(m=>m.code===ref);memberShell('좋은 흐름을 함께 시작해요.','친구의 초대로 연결되는 나의 워크스페이스.',`<div class="member-layout"><section class="invite-welcome"><span class="pill">YOU’RE INVITED</span><h2>${referrer?escape(referrer.name)+'님이 초대했어요.':ref?'친구가 FLOW에 초대했어요.':'FLOW에 오신 것을 환영해요.'}</h2><p>내 현황을 한눈에 확인하고,<br>친구와 함께 새로운 기회를 만나보세요.</p><div class="invite-steps"><span>01 회원가입</span><span>02 본인 인증</span><span>03 추천 연결</span></div>${ref?`<div class="inviter-label">초대 코드 <strong>${escape(ref)}</strong><small>${referrer?'이 기기의 데모 회원에서 확인했습니다.':'추천인 정보는 실제 서비스 연결 후 확인됩니다.'}</small></div>`:''}</section><section class="panel join-form"><h2>회원가입 체험</h2><p class="notice">실제 가입이 아닌 데모입니다. 이메일·전화번호를 수집하지 않습니다.</p><form id="join-demo"><label class="field">표시 이름<input name="name" required minlength="2" maxlength="24" autocomplete="off" placeholder="예: 지민"></label><label class="field">추천코드 <span class="optional">선택</span><input name="ref" value="${escape(ref)}" maxlength="8" pattern="[A-Za-z0-9]{8}" placeholder="8자리 추천코드" autocapitalize="characters"></label><p class="control-hint">가입 시 추천코드가 자동 생성됩니다. 추천 관계는 가입 후 변경할 수 없습니다.</p><label class="consent"><input type="checkbox" required> 이 기기에 저장되는 데모 가입임을 확인했습니다.</label><div id="join-error" role="alert"></div><button class="primary" type="submit">가입하고 내 코드 만들기</button></form>${active()?'<a class="member-back" href="#member">내 계정으로 돌아가기</a>':''}</section></div>`);return}
 const m=active();if(!m){memberShell('내 계정','회원가입과 추천 연결 흐름을 체험해보세요.',`<section class="panel member-empty"><h2>아직 생성한 데모 계정이 없습니다.</h2><p>가입하면 내 추천코드와 초대 링크가 생깁니다.</p><a class="primary" href="#join">회원가입 체험하기</a></section>`);return}
 const parent=state.members.find(u=>u.code===m.ref);memberShell('내 계정','가입부터 인증, 추천 연결까지 한곳에서.',`<div class="member-layout"><section class="panel"><div class="section-top"><h2>${escape(m.name)}님</h2>${badge(m)}</div><label class="field">데모 계정 전환<select id="demo-member">${state.members.map(u=>`<option value="${escape(u.id)}" ${u.id===m.id?'selected':''}>${escape(u.name)}</option>`).join('')}</select></label><p class="notice">${memoryOnly?'저장 공간을 사용할 수 없어 이 페이지에서만 유지됩니다.':'계정과 추천 내역은 이 브라우저에만 저장되는 데모입니다.'} 실제 로그인 및 본인 인증은 연결되어 있지 않습니다.</p><div class="member-detail"><span>내 추천코드</span><b>${m.code}</b></div><div class="member-detail"><span>나를 초대한 추천인</span><b>${parent?escape(parent.name):m.ref?'확인 대기':'직접 가입'}</b></div>${m.ref?`<div class="member-detail"><span>추천 연결 상태</span><b>${parent?(m.verified&&parent.verified?'데모 연결 완료':!parent.verified?'초대자 인증 대기':'본인 인증 대기'):'서버 확인 필요'}</b></div>`:''}<a class="secondary member-back" href="#rewards">내 초대 현황 보기 ↗</a></section><section class="panel"><h2>가입·인증 진행 상태</h2><ol class="verification-steps"><li class="done"><b>회원가입</b><span>데모 계정과 고유 추천코드 생성 완료</span></li><li class="${m.verified?'done':''}"><b>본인 인증</b><span>${m.verified?'데모에서 인증 완료 상태로 변경됨':'실서비스에서는 이메일 또는 휴대폰 인증 필요'}</span></li><li class="${m.verified&&parent?.verified?'done':''}"><b>추천 연결 확인</b><span>${!m.ref?'초대 없이 직접 가입한 회원입니다.':!parent?'외부 추천코드는 서버에서 확인해야 합니다.':!parent.verified?'초대자도 본인 인증을 완료해야 합니다.':m.verified?'양쪽의 데모 인증이 완료되었습니다.':'인증 전에는 추천 목록에 대기 상태로 표시됩니다.'}</span></li></ol>${!m.verified?'<button class="primary" data-ref-action="verify">데모 인증 완료 처리</button>':'<p class="notice">실제 본인 인증을 수행한 상태는 아닙니다.</p>'}</section></div>`)}
 function rewards(){const m=active();if(!m)return `<section class="panel member-empty"><h2>나만의 초대 링크를 만들어보세요.</h2><p>회원가입 후 추천코드가 자동 생성되고,<br>친구가 가입하면 추천 현황에서 확인할 수 있습니다.</p><a href="#join" class="primary">회원가입 체험하기</a><p class="control-hint">현재는 이 브라우저에만 저장되는 데모입니다.</p></section>`;const friends=invited(m),complete=friends.filter(u=>u.verified);return `<div class="referral-summary"><section class="panel referral-link-card"><div class="section-top"><h2>${escape(m.name)}님의 초대 링크</h2>${badge(m)}</div><strong class="my-code">${m.code}</strong><p>내 링크로 가입한 친구를 여기서 확인하세요.</p><label class="field">내 초대 링크<input readonly aria-label="내 초대 링크" value="${escape(link(m))}" onclick="this.select()"></label><div class="ref-actions"><button class="primary" data-ref-action="share">친구에게 공유</button><button class="secondary" data-ref-action="copy-link">링크 복사</button><button class="secondary" data-ref-action="copy-code">코드 복사</button></div><button class="preview-friend" data-ref-action="friend-preview">친구에게 보이는 화면 보기 ↗</button></section><div class="ref-metrics"><section class="stat"><div class="stat-label">초대한 친구</div><strong>${friends.length}</strong><small>명</small></section><section class="stat"><div class="stat-label">데모 인증 완료</div><strong>${complete.length}</strong><small>명</small></section><section class="stat"><div class="stat-label">인증 대기</div><strong>${friends.length-complete.length}</strong><small>명</small></section><section class="stat"><div class="stat-label">지급된 보상</div><strong>0</strong><small>보상 지급 미연동</small></section></div></div><section class="panel"><div class="section-top"><h2>내 추천 현황</h2><a class="text-button" href="#member">내 인증 상태 확인 ↗</a></div>${friends.length?`<div class="friend-list">${friends.map(u=>`<div class="friend-row"><span class="avatar">${escape(u.name.slice(0,1))}</span><div><b>${escape(u.name)}</b><small>${escape(u.created.slice(0,10))} 가입</small></div>${badge(u)}<span class="reward-pending">보상 미지급</span></div>`).join('')}</div>`:'<div class="empty">아직 초대한 친구가 없습니다.<p>초대 링크를 공유하고 함께 시작해보세요.</p></div>'}</section><p class="notice">이 기기의 데모 데이터입니다. 다른 기기에서 가입한 친구의 연결·인증·보상은 서버 연결 후 사용할 수 있습니다. 실제 보상은 지급되지 않습니다.</p>`}
 document.addEventListener('submit',e=>{if(e.target.id!=='join-demo')return;e.preventDefault();const data=new FormData(e.target),name=String(data.get('name')||'').trim(),ref=String(data.get('ref')||'').trim().toUpperCase(),error=$('#join-error');if(name.length<2||name.length>24){error.textContent='이름을 2~24자로 입력해주세요.';return}if(state.members.some(m=>m.name.toLocaleLowerCase()===name.toLocaleLowerCase())){error.textContent='이 기기에 같은 이름의 데모 계정이 있습니다. 내 계정에서 전환하거나 다른 이름을 사용해주세요.';return}if(ref&&!/^[A-Z0-9]{8}$/.test(ref)){error.textContent='추천코드는 영문·숫자 8자리입니다.';return}const m={id:crypto.randomUUID(),name,code:code(),ref,verified:false,created:new Date().toISOString()};state.members.push(m);state.active=m.id;write();const url=new URL(location.href);url.searchParams.delete('ref');url.hash='member';history.replaceState(null,'',url);render('member');toast(memoryOnly?'데모 계정 생성 완료. 기기 저장은 사용할 수 없습니다.':'데모 가입 완료. 내 추천코드가 생성되었습니다.')});
 document.addEventListener('change',e=>{if(e.target.id==='demo-member'&&state.members.some(m=>m.id===e.target.value)){state.active=e.target.value;write();render('member')}});
 async function copy(value){try{await navigator.clipboard.writeText(value);toast('복사했습니다.')}catch{modal('직접 복사해주세요',`<label class="field">복사할 내용<input readonly value="${escape(value)}" onclick="this.select()"></label>`)}}
 document.addEventListener('click',async e=>{const action=e.target.closest('[data-ref-action]')?.dataset.refAction,m=active();if(!action||!m)return;if(action==='verify'){m.verified=true;write();render('member');toast('데모 인증 상태가 변경되었습니다.')}if(action==='copy-link')await copy(link(m));if(action==='copy-code')await copy(m.code);if(action==='friend-preview'){history.pushState(null,'',link(m));window.dispatchEvent(new HashChangeEvent('hashchange'))}if(action==='share'){try{if(navigator.share)await navigator.share({title:'FLOW에 초대합니다',text:m.name+'님이 초대했어요. 함께 시작해보세요.',url:link(m)});else await copy(link(m))}catch(e){if(e.name!=='AbortError')toast('공유할 수 없습니다. 링크 복사를 이용해주세요.')}}});
 if(incoming()&&!new URLSearchParams(location.search).has('design-preview')){location.hash='join'}
 return {render,rewards,displayName,decorate};
})();
